head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > useFilterListSync]\nDataList 의 setColumnFilter() 메소드로 필터링한 경우 FilterList 를 동기화합니다.",
    "validation" : [
        "GridView 의 useFilterList 속성으로 FilterList 기능이 적용된 경우에 동작합니다.",
        "(FilterList 적용 전제) true 설정 시, Column 의 FilterList 에 전체 목록을 표시하고 필터로 GridView 에 표시되지 않은 데이터는 체크가 해제됩니다.",
        "(FilterList 적용 전제) true 설정 시, 마지막에 필터가 설정된 Column 만 적용되며 다른 Column 은 GridView 에 표시된 데이터만 FilterList 에 표시됩니다.",
        "(FilterList 적용 전제) false 설정 시, Column 의 FilterList 에 GridView 에 표시된 데이터만 표시됩니다.",
        "(FilterList 적용 전제) 미설정 시, Column 의 FilterList 에 GridView 에 표시된 데이터만 표시됩니다.",
        "GroupBy 기능이 적용된 경우에 useFilterListSync 속성은 동작하지 않습니다.",
    ]
}



scwin.onpageload = async function () {
    // 공통 Global DataList(gdl_boolean 등) 생성
    $c.gcm.createCommonDatalist();

    // 정적 select1(gdl_boolean) 은 초기 selectedIndex 미적용 → 기본값(미설정='1') 명시 설정
    con_useFilterListSync.setValue("1");
    con_groupBy.setValue("1");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (con 값은 렌더 시 결정 → Target 재생성 버튼으로만 반영)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기 (gdl_boolean 바인딩 → getText : '' / 'true' / 'false')
    let vSync = con_useFilterListSync.getText();
    let vGroupBy = con_groupBy.getText();
    let useGroupBy = (vGroupBy === 'true');

    // 현재 설정/검증 안내 라벨 (target 생성 전 가장 먼저 생성)
    let lbl = '';
    lbl += '[전제] col1(A~D) / col2(X,Y) / col3,col4(값). 전체 Header Column 은 useFilter=true 고정이며';
    lbl += '\n   GridView 는 useFilterList=true 고정으로 FilterList 기능이 적용된 상태이다.';
    lbl += '\n현재 useFilterListSync=' + (vSync === '' ? '(미설정=false)' : vSync) + ' / groupBy=' + (useGroupBy ? 'true(그룹핑 적용)' : '(미적용)');
    lbl += '\n[절차] (1) (col1 필터 적용) 클릭 -> setColumnFilter 로 col1=A 만 남김(B,C,D 행이 GridView 에서 제외됨).';
    lbl += '\n   -> 필터 적용 시 해당 컬럼(col1 필터->col1 / col2 필터->col2)의 FilterList 표시목록/체크상태가 결과창에 자동 출력된다.';
    lbl += '\n[확인] true 설정 시 col1 FilterList 는 전체(A~D) 표시 + 제외값(B,C,D) 체크해제 / false(또는 미설정) 시 표시된 값(A)만 표시.';
    lbl += '\n(2) (col2 필터 적용) 으로 마지막 필터를 col2 로 바꾸면 : true 시 col2 만 전체목록 유지, col1 은 표시된 데이터만 표시로 복귀(자동 출력).';
    lbl += '\n[groupBy] groupBy=true 로 재생성하면 그리드가 그룹핑되어 useFilterListSync=true 여도 FilterList 동기화가 동작하지 않음.';
    $c.gcm.createLabel('label="' + lbl + '"', '', 'label1');

    // dataList 직접 생성 (col1 = A~D 4종, col2 = X,Y 2종 → 필터로 표시/비표시 데이터 구분)
    let ns = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + ns + ' id="dlt_bind" baseNode="list" repeatNode="map" saveRemovedData="true">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true"></w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);
    let arrDl = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDl[arrDl.length - 1];

    let cats = ["A", "B", "C", "D"];
    let types = ["X", "Y"];
    let jsonData = [];
    for (let i = 0; i < 12; i++) {
        jsonData.push({
            "col1": cats[i % 4],
            "col2": types[Math.floor(i / 3) % 2],
            "col3": "name_" + (i + 1),
            "col4": "" + (i + 1)
        });
    }
    scwin.dlt_bind.setJSON(jsonData, false);

    // target 생성 : 전체 컬럼 useFilter 고정 + useFilterList=true 고정, useFilterListSync 만 con 값 적용(미설정 시 속성 생략)
    let attrSync = (vSync === '') ? '' : ' useFilterListSync="' + vSync + '"';

    let grp_comp = $c.gcm.getTestGroup();
    let s = '';
    s += '<w2:gridView ' + ns + ' useFilterList="true"' + attrSync + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:430px;height:220px;">';
    s += '<w2:caption style="" id="caption1" value="useFilterListSync 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="100" style="" inputType="text" id="column1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="column2" value="col2" useFilter="true"></w2:column>';
    s += '<w2:column width="110" style="" inputType="text" id="column3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="column4" value="col4" useFilter="true"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="110" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);

    // groupBy=true 이면 col1(인덱스 0) 기준 그룹핑 적용 (이 상태에서는 useFilterListSync 동기화 미동작)
    // groupbyHeader 로 그룹 header 행에 그룹값/건수를 표시(미설정 시 header/footer 가 빈 행으로 보임), footer 는 숨김
    if (useGroupBy) {
        target1.groupby({
            sortIndex: [0],
            sortOrder: [1],
            groupbyHeader: { depth_0: [{ colSpan: "4", inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" }] },
            hideFooter: true
        });
    }
}



// (1) col1 필터 적용 : setColumnFilter() 로 col1=A 만 남김 → B,C,D 행이 GridView 에서 제외 → FilterList 자동 출력
scwin.btn_filterCol1_onclick = function () {
    dlt_bind.setColumnFilter({ type: "row", colIndex: "col1", key: "A", condition: "and", exactMatch: true });
    wf_body_bottom.getObj("scwin").setReturnValue("=====col1 필터(A) 적용 (마지막 필터=col1)===== 표시 행 수 : " + target1.getDataLength());
    scwin.dumpFilterList(0, "col1");
}



// (3) col2 필터 추가 적용 : 마지막 필터를 col2 로 변경 → true 시 col2 만 전체목록 유지 → FilterList 자동 출력
scwin.btn_filterCol2_onclick = function () {
    dlt_bind.setColumnFilter({ type: "row", colIndex: "col2", key: "X", condition: "and", exactMatch: true });
    wf_body_bottom.getObj("scwin").setReturnValue("=====col2 필터(X) 추가 적용 (마지막 필터=col2)===== 표시 행 수 : " + target1.getDataLength());
    // 마지막 필터 컬럼(col2) → 다른 컬럼(col1) 순으로 FilterList 를 출력해 적용 대상 전환을 확인
    scwin.dumpFilterList(1, "col2", function () {
        scwin.dumpFilterList(0, "col1");
    });
}



// 필터 초기화
scwin.btn_clearFilter_onclick = function () {
    dlt_bind.clearFilter();
    wf_body_bottom.getObj("scwin").setReturnValue("=====필터 초기화===== 표시 행 수 : " + target1.getDataLength());
}



// FilterList 표시목록 + 체크상태 출력 : 헤더 필터 아이콘을 클릭해 FilterList 드롭다운을 연 뒤 목록/체크상태를 결과창에 출력
// (콘솔의 showCustomFilter2 는 "사용자 지정 필터" 조건 팝업이라 FilterList 체크박스 목록이 아님 → 아이콘 클릭으로 연다)
scwin.dumpFilterList = function (colIdx, colLabel, onDone) {
    let icons = document.querySelectorAll('.w2grid_customFilter_open');
    if (!icons || icons.length <= colIdx) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + colLabel + "] 필터 아이콘을 찾을 수 없습니다. (Target 재생성 후 다시 시도)");
        if (onDone) onDone();
        return;
    }

    let readOut = function () {
        let sv = function (s) { wf_body_bottom.getObj("scwin").setReturnValue(s); };
        let vSync = con_useFilterListSync.getText();
        sv("===== [" + colLabel + "] FilterList (useFilterListSync=" + (vSync === '' ? '미설정=false' : vSync) + ") =====");

        let cbs = Array.prototype.slice.call(document.querySelectorAll('.w2grid_customFilter_list_listColumn_checkbox'))
            .filter(function (el) { return el.offsetParent !== null; });

        let cnt = 0;
        cbs.forEach(function (cb) {
            let row = cb.closest('tr,li,div');
            let txt = '';
            if (row) {
                let c = row.cloneNode(true);
                Array.prototype.slice.call(c.querySelectorAll('input')).forEach(function (x) { x.remove(); });
                txt = (c.textContent || '').trim();
            }
            // 컨트롤 행(사용자필터/전체선택) 및 빈 항목 제외 → 데이터 아이템만 출력
            if (txt === '' || txt === '사용자필터' || txt === '전체선택') return;
            sv("  - " + txt + " : " + (cb.checked ? '체크' : '해제'));
            cnt++;
        });
        if (cnt === 0) {
            sv("  FilterList 표시목록 없음 -> useFilterListSync 동기화 미동작");
        } else {
            sv("  (표시 아이템 " + cnt + "개)");
        }
    };

    // 아이콘 클릭은 토글 → 이미 열려있어 닫힌 경우(가시 항목 0) 한 번 더 열어 읽는다
    let openAndRead = function (attempt) {
        icons[colIdx].click();
        setTimeout(function () {
            let visible = Array.prototype.slice.call(document.querySelectorAll('.w2grid_customFilter_list_listColumn_checkbox'))
                .filter(function (el) { return el.offsetParent !== null; }).length;
            if (visible === 0 && attempt < 2) { openAndRead(attempt + 1); return; }
            readOut();
            if (onDone) onDone();
        }, 350);
    };
    openAndRead(1);
}
